  "findings": {
    "ua": [
      {
        "h": "1. Минулий тиждень трохи кращий, але рівень лишається високим",
        "p": "ODR ринку зріс з <b>22.6%</b> (10 серп) до <b>20.6%</b> (26 жовт) — це -2.0 п.п. за 12 тижнів. Минулий тиждень: 20.6% проти 21.5% тижнем раніше, обсяг 10.8k замовлень (було 11.5k)."
      },
      {
        "h": "2. Проблема = grocery, а не Stores у цілому",
        "p": "<b>VARUS</b> тримає ODR <b>60.3%</b> (ост. тиждень 54.7%) і сам по собі визначає ринковий рівень. <b>KOPIYKA</b> 30.1% (-11.5 п.п.), <b>SANTIM</b> 27.8% (-11.4 п.п.), <b>KOPIYKA MINI</b> 23.3% (-5.8 п.п.). Алкогольні мережі в ТОП-15 лишаються на <b>0%</b>."
      },
      {
        "h": "3. Є партнери з реальним прогресом — їх процеси треба тиражувати",
        "p": "<b>TAISTRA</b> -0.7 п.п. (ост. 15.8%), <b>RUKAVYCHKA</b> +2.0 п.п. (ост. 22.4%). ODR керований на рівні партнера без змін у продукті."
      },
      {
        "h": "4. Стрибок price defect 10 серпня виглядає як артефакт, не клієнтський біль",
        "p": "На тижні 10 серп price-дефектів було 3721 шт., минулого тижня — 0 шт. Quantity лишається головним драйвером (73.2% усіх item defects). Пакети та OOS на напоях треба чистити окремо від KPI."
      }
    ],
    "en": [
      {
        "h": "1. Last week improved slightly, but the level stays high",
        "p": "Market ODR grew from <b>22.6%</b> (10 Aug) to <b>20.6%</b> (26 Oct) — -2.0 pp over 12 weeks. Last week: 20.6% vs 21.5% the week before, on 10.8k orders (previously 11.5k)."
      },
      {
        "h": "2. The problem is grocery, not Stores as a whole",
        "p": "<b>VARUS</b> holds ODR at <b>60.3%</b> (latest week 54.7%) and sets the market level. <b>KOPIYKA</b> 30.1% (-11.5 pp), <b>SANTIM</b> 27.8% (-11.4 pp), <b>KOPIYKA MINI</b> 23.3% (-5.8 pp). Alcohol chains in the top-15 stay at <b>0%</b>."
      },
      {
        "h": "3. Some partners genuinely improved — their processes should be replicated",
        "p": "<b>TAISTRA</b> -0.7 pp (latest 15.8%), <b>RUKAVYCHKA</b> +2.0 pp (latest 22.4%). ODR is manageable at partner level without product changes."
      },
      {
        "h": "4. The 10 Aug price-defect spike looks like an accounting artefact",
        "p": "Price defects peaked at 3721 items in the week of 10 Aug and were 0 last week. Quantity remains the main driver (73.2% of item defects). Bags and beverage OOS should be cleaned up separately from the KPI."
      }
    ]
  },
